function e(n,x){return`{X: ${n.x.toFixed(x)} Y: ${n.y.toFixed(x)}}`}function V(n,x){return n.x*x.x+n.y*x.y+n.z*x.z}function i(n){return n.x*n.x+n.y*n.y+n.z*n.z}function f(n){return Math.sqrt(i(n))}function t(n,x){const o=x.x-n.x,y=x.y-n.y,z=x.z-n.z;return o*o+y*y+z*z}function c(n,x){return Math.sqrt(t(n,x))}function F(n,x,o,y){return y.x=n,y.y=x,y.z=o,y}function r(n,x,o){return o.x=n.x*x,o.y=n.y*x,o.z=n.z*x,o}function T(n,x){return n.x*=x,n.y*=x,n.z*=x,n}function d(n,x,o){return o.x=n.x-x.x,o.y=n.y-x.y,o.z=n.z-x.z,o}function $(n,x){return x.x=n.x,x.y=n.y,x.z=n.z,x}function u(n,x,o,y){return y.x=n.x+(x.x-n.x)*o,y.y=n.y+(x.y-n.y)*o,y.z=n.z+(x.z-n.z)*o,y}function R(n,x){const o=f(n);return o===0?(x.x=0,x.y=0,x.z=0):(x.x=n.x/o,x.y=n.y/o,x.z=n.z/o),x}function S(n,x,o){return(o.x-n.x)*x.x+(o.y-n.y)*x.y+(o.z-n.z)*x.z}function h(n,x){return`{X: ${n.x.toFixed(x)} Y: ${n.y.toFixed(x)} Z: ${n.z.toFixed(x)}}`}function D(n,x){return n.x*x.x+n.y*x.y+n.z*x.z+n.w*x.w}function q(n,x){return`{X: ${n.x.toFixed(x)} Y: ${n.y.toFixed(x)} Z: ${n.z.toFixed(x)} W: ${n.w.toFixed(x)}}`}export{c as V,$ as a,d as b,V as c,D as d,F as e,q as f,h as g,e as h,t as i,f as j,i as k,u as l,R as m,T as n,r as o,S as p};
